insert into pay (
	pay_id
	, user_id
	, product_id
	, pay_method
	, card_name
	, card_num
	, pay_price
	, pay_date
	, pay_status
)
values (
	#{payId}
	, #{userId}
	, #{productId}
	, #{payMethod}
	, #{cardName}
	, #{cardNum}
	, #{payPrice}
	, #{payDate}
	, #{payStatus}
)

insert into user_product(
	pay_id
	, product_id
	, user_id
	, remaining_count
)
values(
	#{payId}
	, #{productId}
	, #{userId}
	, (
		select	product_count
		from	product
		where	product_id = #{productId}
	)
)

insert into com_product(
	pay_id
	, product_id
	, user_id
	, start_date
	, end_date
)
values(
	#{payId}
	, #{productId}
	, #{userId}
	, #{payDate}
	, adddate(#{payDate}, (
		select	product_duration
		from	product
		where	product_id = #{productId}
	))
)
